use rand::Rng;
let mut backoff = Duration::from_secs(1);
for _ in 0..3 {
    if make_rpc_call().is_ok() { break; }
    let jitter = rand::thread_rng().gen_range(0..100);
    tokio::time::sleep(backoff + Duration::from_millis(jitter)).await;
